// Look of the launcher: Qt's modern Windows style ("windows11", follows the system dark/light
// scheme), Fusion with a dark palette where that style is unavailable, status colours readable on both
// schemes, and the original launcher icon (resources/icon, generated by launcher/tools/gen_icon.py).
#pragma once

#include "core/exit_codes.h"
#include "core/validation.h"

#include <QColor>
#include <QIcon>
#include <QPixmap>
#include <QString>

class QApplication;
class QWidget;

namespace fl::ui {

// requestedScheme: "" (follow the system), "light" or "dark" (screenshots).
void ApplyAppStyle(QApplication& app, const QString& requestedScheme = QString());
bool IsDarkMode();

QColor SeverityColor(Severity severity);
QColor ToneColor(ExitTone tone);
QColor MutedTextColor(const QWidget* widget);
QString ColorCss(const QColor& color);  // "#rrggbb"

QIcon AppIcon();
QPixmap AppIconPixmap(int logicalSize, qreal devicePixelRatio);

// A label font scaled relative to the widget's font (no fixed pixel sizes: high DPI).
void ScaleFont(QWidget* widget, qreal factor, bool bold = false);

// Asks before an edit that changes several settings at once (resets of the controls tab; review M4 finding 14):
// a question box with `acceptText` and "Abbrechen" (default). Tests and automation install a hook instead of the box
// (nullptr restores the box); the hook gets the question text and returns the answer.
using ConfirmHook = bool (*)(const QString& text);
void SetConfirmHook(ConfirmHook hook);
bool ConfirmChange(QWidget* parent, const QString& text, const QString& acceptText);

}  // namespace fl::ui
